use pervasive::seq::Seq;         // for Seq<T>
use pervasive::vec::Vec;         // for Vec<T>

/// copy returns a new Vec<T> containing exactly the same elements (in order)
/// as `a`.  We prove that the returned vector’s .as_seq() equals `a.as_seq()`.
#[requires(true)]
#[ensures(result.as_seq() == a.as_seq())]
fn copy<T: Copy>(a: &Vec<T>) -> Vec<T> {
    // Allocate an empty vector with capacity = a.len()
    let mut result = Vec::with_capacity(a.len());
    // Ghost‐bind the sequence of the input so we can talk about prefixes
    let s: Seq<T> = a.as_seq();
    // We will iterate by index i
    let mut i: usize = 0;
    // Loop over indices 0..a.len()
    while i < a.len() {
        // Standard well‐foundedness / termination metric
        decreases(a.len() - i);
        // i never exceeds a.len()
        invariant(i <= a.len());
        // result so far holds exactly the prefix s[0..i]
        invariant(result.as_seq().len() == i);
        invariant(result.as_seq() == s.prefix(i));

        // Body: copy a[i] into result
        let item: T = a[i];
        result.push(item);
        i += 1;
    }
    result
}

